import React from 'react';

import clsx from 'clsx';

import styles from './styles.module.less';

interface IA4PageProps extends React.HTMLAttributes<HTMLDivElement> {}

const A4Page: React.FC<IA4PageProps> = ({ children, className, ...rest }) => {
  return (
    <section {...rest} className={clsx(className, styles.a4page)}>
      {children}
    </section>
  );
};

export default A4Page;

export const A4SubPage: React.FC<IA4PageProps> = ({ children, className, ...rest }) => {
  return (
    <section {...rest} className={clsx(className, styles.subpage)}>
      {children}
    </section>
  );
};
